import { mkdir, mkdtemp, readdir, rm, utimes, writeFile, } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { IDLE_RECHECK_MS, LAUNCH_LOOKUP_MAX_MS, MIN_REFRESH_GAP_MS, POLL_FALLBACK_REFRESH_MS, parseExperimentEvent, parseSessionExperiments, pruneStaleSessionFolders, SESSION_FOLDER_MAX_AGE_MS, STALL_AFTER_MS, STREAM_FALLBACK_REFRESH_MS, sessionExperimentsPath, splitSseData, watchSessionExperiments, } from "./watchRunningExperiments.js";
const A = "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa";
const B = "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb";
function status(experimentId, overrides = {}) {
    return {
        experimentId,
        status: "pending",
        finishedCount: 0,
        remainingCount: 4,
        traceCount: 0,
        resumable: true,
        ...overrides,
    };
}
function line(experimentId, name) {
    return { experimentId, launchId: null, name, startedAt: null };
}
function sequence(values) {
    const queue = [...values];
    return () => (queue.length > 1 ? queue.shift() : queue[0]);
}
function fakeDeps(opts) {
    let clock = 0;
    const nextFile = sequence(opts.files);
    const perExperiment = Object.fromEntries(Object.entries(opts.statuses ?? {}).map(([id, list]) => [
        id,
        sequence(list),
    ]));
    let captured;
    let fileChanged = () => { };
    const perLaunch = Object.fromEntries(Object.entries(opts.launches ?? {}).map(([id, list]) => [
        id,
        sequence(list),
    ]));
    const nextConnection = sequence(opts.connections ?? ["server"]);
    const deps = {
        connection: () => nextConnection(),
        snapshots: [],
        waits: [],
        wakes: [],
        statusReads: [],
        launchLookups: [],
        findLaunch: async (launchId) => {
            deps.launchLookups.push(launchId);
            return perLaunch[launchId]?.() ?? null;
        },
        streamsOpened: 0,
        streamsOpenAtWait: [],
        fileWatchStopped: false,
        openSignals: [],
        readSessionExperiments: async () => {
            const next = nextFile();
            if (next instanceof Error) {
                throw next;
            }
            return next;
        },
        watchSessionFile: (onChange) => {
            fileChanged = onChange;
            return () => {
                deps.fileWatchStopped = true;
            };
        },
        readStatus: async (id) => {
            deps.statusReads.push(id);
            const next = perExperiment[id];
            if (!next) {
                throw new Error(`no status for ${id}`);
            }
            return next();
        },
        experimentUrl: (id) => `https://bitfab.test/experiments?experimentIds=${id}`,
        openStream: (onEvent, signal) => {
            deps.streamsOpened += 1;
            captured = onEvent;
            deps.openSignals.push(signal);
            if (opts.stream === "unavailable") {
                return Promise.resolve("unavailable");
            }
            return new Promise((resolve) => {
                signal.addEventListener("abort", () => resolve("ended"));
            });
        },
        emit: (snapshot) => {
            deps.snapshots.push(snapshot);
        },
        now: () => clock,
        wait: async (ms, wake) => {
            let woken = false;
            void wake.then(() => {
                woken = true;
            });
            await new Promise((resolve) => setTimeout(resolve, 0));
            opts.duringWait?.({
                onEvent: captured,
                onFileChange: fileChanged,
                loop: deps.waits.length,
            });
            await new Promise((resolve) => setTimeout(resolve, 0));
            deps.waits.push(ms);
            deps.wakes.push(woken);
            deps.streamsOpenAtWait.push(deps.openSignals.some((signal) => !signal.aborted));
            clock += woken ? MIN_REFRESH_GAP_MS : ms;
        },
        shouldStop: () => deps.waits.length >= opts.loops,
    };
    return deps;
}
describe("watchSessionExperiments", () => {
    it("reads only the local file while nothing runs, with no server call or stream", async () => {
        const deps = fakeDeps({ files: [[]], loops: 3 });
        await watchSessionExperiments(deps);
        expect(deps.snapshots).toEqual([{ running: [], finished: [] }]);
        expect(deps.statusReads).toEqual([]);
        expect(deps.streamsOpened).toBe(0);
        expect(deps.waits).toEqual([
            IDLE_RECHECK_MS,
            IDLE_RECHECK_MS,
            IDLE_RECHECK_MS,
        ]);
        expect(deps.fileWatchStopped).toBe(true);
    });
    it("shows a new experiment's progress, then its finish, and closes the stream once nothing runs", async () => {
        const deps = fakeDeps({
            files: [[], [line(A, "shorter prompt")]],
            statuses: {
                [A]: [
                    status(A, { finishedCount: 1, remainingCount: 3 }),
                    status(A, {
                        status: "completed",
                        finishedCount: 4,
                        remainingCount: 0,
                    }),
                ],
            },
            loops: 3,
            duringWait: ({ onEvent, loop }) => {
                if (loop === 1) {
                    onEvent?.({ experimentId: A });
                }
            },
        });
        await watchSessionExperiments(deps);
        const url = `https://bitfab.test/experiments?experimentIds=${A}`;
        expect(deps.snapshots).toEqual([
            { running: [], finished: [] },
            {
                running: [
                    {
                        id: A,
                        name: "shorter prompt",
                        finished: 1,
                        total: 4,
                        url,
                        stalled: false,
                    },
                ],
                finished: [],
            },
            {
                running: [],
                finished: [
                    {
                        id: A,
                        name: "shorter prompt",
                        status: "completed",
                        url,
                        announce: true,
                    },
                ],
            },
        ]);
        expect(deps.streamsOpened).toBe(1);
        expect(deps.streamsOpenAtWait).toEqual([false, true, false]);
        expect(deps.wakes).toEqual([false, true, false]);
        expect(deps.waits).toEqual([
            IDLE_RECHECK_MS,
            STREAM_FALLBACK_REFRESH_MS,
            IDLE_RECHECK_MS,
        ]);
    });
    it("shows experiments already finished when the watch starts, marked not to announce, and reads them once", async () => {
        const deps = fakeDeps({
            files: [[line(A, "old run")]],
            statuses: { [A]: [status(A, { status: "completed" })] },
            loops: 2,
        });
        await watchSessionExperiments(deps);
        expect(deps.snapshots).toEqual([
            {
                running: [],
                finished: [
                    {
                        id: A,
                        name: "old run",
                        status: "completed",
                        url: `https://bitfab.test/experiments?experimentIds=${A}`,
                        announce: false,
                    },
                ],
            },
        ]);
        expect(deps.statusReads).toEqual([A]);
    });
    it("drops an experiment the server cannot find and keeps following the others", async () => {
        const deps = fakeDeps({
            files: [[line(A, "from a test"), line(B, "real run")]],
            statuses: { [A]: [null], [B]: [status(B)] },
            loops: 2,
        });
        await watchSessionExperiments(deps);
        expect(deps.snapshots[0]?.running.map((row) => row.id)).toEqual([B]);
        expect(deps.statusReads.filter((id) => id === A)).toHaveLength(1);
    });
    it("starts over when the login or server changes, following experiments the old one could not read", async () => {
        const deps = fakeDeps({
            connections: ["old", "old", "old", "new"],
            files: [[line(A, "replay")]],
            statuses: { [A]: [null, status(A, { finishedCount: 1 })] },
            loops: 3,
        });
        await watchSessionExperiments(deps);
        expect(deps.snapshots.at(-1)?.running.map((row) => row.id)).toEqual([A]);
        expect(deps.statusReads).toEqual([A, A]);
    });
    it("wakes when the session file changes", async () => {
        const deps = fakeDeps({
            files: [[]],
            loops: 2,
            duringWait: ({ onFileChange, loop }) => {
                if (loop === 0) {
                    onFileChange();
                }
            },
        });
        await watchSessionExperiments(deps);
        expect(deps.wakes).toEqual([true, false]);
    });
    it("wakes on events for its own experiments only", async () => {
        const deps = fakeDeps({
            files: [[line(A, null)]],
            statuses: { [A]: [status(A)] },
            loops: 2,
            duringWait: ({ onEvent, loop }) => {
                if (loop === 0) {
                    onEvent?.({ experimentId: B });
                }
                if (loop === 1) {
                    onEvent?.({ experimentId: A });
                }
            },
        });
        await watchSessionExperiments(deps);
        expect(deps.wakes).toEqual([false, true]);
    });
    it("marks a running experiment stalled after ten minutes without progress", async () => {
        const deps = fakeDeps({
            files: [[line(A, null)]],
            statuses: { [A]: [status(A, { finishedCount: 2, remainingCount: 3 })] },
            loops: Math.ceil(STALL_AFTER_MS / STREAM_FALLBACK_REFRESH_MS) + 1,
        });
        await watchSessionExperiments(deps);
        expect(deps.snapshots[0]?.running[0]?.stalled).toBe(false);
        expect(deps.snapshots.at(-1)?.running[0]?.stalled).toBe(true);
    });
    it("polls faster when the server has no event stream", async () => {
        const deps = fakeDeps({
            files: [[line(A, null)]],
            statuses: { [A]: [status(A)] },
            stream: "unavailable",
            loops: 3,
        });
        await watchSessionExperiments(deps);
        expect(deps.streamsOpened).toBe(1);
        expect(deps.waits.slice(1)).toEqual([
            POLL_FALLBACK_REFRESH_MS,
            POLL_FALLBACK_REFRESH_MS,
        ]);
    });
    it("looks up a cloud launch by its tag until the experiment appears, then follows it", async () => {
        const launch = {
            experimentId: null,
            launchId: "launch-1",
            name: "cloud run",
            startedAt: 0,
        };
        const deps = fakeDeps({
            files: [[launch]],
            launches: { "launch-1": [null, { id: A, name: "server name" }] },
            statuses: { [A]: [status(A, { finishedCount: 1 })] },
            loops: 3,
        });
        await watchSessionExperiments(deps);
        expect(deps.launchLookups).toEqual(["launch-1", "launch-1"]);
        expect(deps.snapshots.at(-1)?.running.map((row) => row.name)).toEqual([
            "cloud run",
        ]);
    });
    it("stops looking for a launch an hour after it started", async () => {
        const deps = fakeDeps({
            files: [
                [
                    {
                        experimentId: null,
                        launchId: "never-started",
                        name: null,
                        startedAt: -LAUNCH_LOOKUP_MAX_MS - 1,
                    },
                ],
            ],
            loops: 2,
        });
        await watchSessionExperiments(deps);
        expect(deps.launchLookups).toEqual([]);
    });
    it("keeps going through failed refreshes, polling until one succeeds", async () => {
        const deps = fakeDeps({
            files: [
                new Error("down"),
                new Error("down"),
                new Error("down"),
                new Error("down"),
                [],
            ],
            loops: 5,
        });
        await expect(watchSessionExperiments(deps)).resolves.toBeUndefined();
        expect(deps.waits.slice(0, 4)).toEqual([
            POLL_FALLBACK_REFRESH_MS,
            POLL_FALLBACK_REFRESH_MS,
            POLL_FALLBACK_REFRESH_MS,
            POLL_FALLBACK_REFRESH_MS,
        ]);
        expect(deps.snapshots).toEqual([{ running: [], finished: [] }]);
        expect(deps.fileWatchStopped).toBe(true);
    });
});
describe("parseSessionExperiments", () => {
    it("keeps this server's experiments and launches and skips the rest", () => {
        const content = [
            JSON.stringify({
                experimentId: A,
                name: "baseline",
                serviceUrl: "http://localhost:3001",
                startedAt: "2026-11-23T21:00:00.000Z",
            }),
            JSON.stringify({
                launchId: B,
                experimentId: null,
                name: null,
                serviceUrl: "http://localhost:3001/",
                startedAt: "2026-11-23T21:00:00Z",
            }),
            JSON.stringify({
                experimentId: "other",
                name: "prod",
                serviceUrl: "https://bitfab.ai",
            }),
            "not json",
            JSON.stringify({ name: "no id", serviceUrl: "http://localhost:3001" }),
            "",
        ].join("\n");
        expect(parseSessionExperiments(content, "http://localhost:3001")).toEqual([
            {
                experimentId: A,
                launchId: null,
                name: "baseline",
                startedAt: Date.parse("2026-11-23T21:00:00.000Z"),
            },
            {
                experimentId: null,
                launchId: B,
                name: null,
                startedAt: Date.parse("2026-11-23T21:00:00Z"),
            },
        ]);
    });
});
describe("pruneStaleSessionFolders", () => {
    it("deletes other sessions' folders untouched for a week and keeps the rest", async () => {
        const root = await mkdtemp(join(tmpdir(), "bitfab-sessions-"));
        const now = Date.now();
        const old = new Date(now - SESSION_FOLDER_MAX_AGE_MS - 60_000);
        const folder = async (name, writtenAt) => {
            await mkdir(join(root, name));
            if (writtenAt !== null) {
                const file = join(root, name, "experiments.jsonl");
                await writeFile(file, "{}\n");
                await utimes(file, writtenAt, writtenAt);
            }
        };
        await folder("stale", old);
        await folder("current", old);
        await folder("recent", new Date(now - 60_000));
        await folder("empty-recent", null);
        await writeFile(join(root, "stray-file"), "");
        await utimes(join(root, "stray-file"), old, old);
        const removed = await pruneStaleSessionFolders(root, "current", now);
        expect(removed).toEqual(["stale"]);
        expect((await readdir(root)).sort()).toEqual([
            "current",
            "empty-recent",
            "recent",
            "stray-file",
        ]);
        await rm(root, { recursive: true, force: true });
    });
    it("does nothing when the folder does not exist yet", async () => {
        await expect(pruneStaleSessionFolders(join(tmpdir(), "bitfab-missing-root"), "s", 0)).resolves.toEqual([]);
    });
});
describe("sessionExperimentsPath", () => {
    it("builds the session folder and refuses an id that could leave it", () => {
        expect(sessionExperimentsPath("/home/me", "session-1")).toBe("/home/me/.bitfab/agent-sessions/session-1");
        expect(sessionExperimentsPath("/home/me", "../escape")).toBeNull();
        expect(sessionExperimentsPath("/home/me", "a/b")).toBeNull();
    });
});
describe("splitSseData", () => {
    it("returns each complete message's event and data and keeps the partial tail", () => {
        const { messages, rest } = splitSseData('event: experiment:updated\ndata: {"a":1}\n\n: comment\n\nevent: ping\ndata: {"b"');
        expect(messages).toEqual([{ event: "experiment:updated", data: '{"a":1}' }]);
        expect(rest).toBe('event: ping\ndata: {"b"');
    });
});
describe("parseExperimentEvent", () => {
    it("reads the experiment id", () => {
        expect(parseExperimentEvent({
            event: "experiment:updated",
            data: JSON.stringify({
                experimentId: A,
                experiment: { agentSessionId: "session-1" },
            }),
        })).toEqual({ experimentId: A });
    });
    it("reads the old testRunId key", () => {
        expect(parseExperimentEvent({
            event: "experiment-stats:updated",
            data: JSON.stringify({ testRunId: A }),
        })).toEqual({ experimentId: A });
    });
    it("drops pings, other event types, and unreadable data", () => {
        expect(parseExperimentEvent({ event: "ping", data: "{}" })).toBeNull();
        expect(parseExperimentEvent({
            event: "label:updated",
            data: JSON.stringify({ experimentId: A }),
        })).toBeNull();
        expect(parseExperimentEvent({ event: "experiment:updated", data: "not json" })).toBeNull();
        expect(parseExperimentEvent({
            event: null,
            data: JSON.stringify({ experimentId: A }),
        })).toBeNull();
    });
});
